    uint256 reverse = FixedHelper.calculateFixedSwapByRatio(forward, packedRatio, false);

    // Profit should be at most 2 wei (one rounding per direction)
    if (reverse > amount) {
        assertLe(reverse - amount, 2, "Round-trip profit bounded by 2 wei");
    }
}

